public class ExchangeRateClient {
    private static final Pattern CURRENCY_PATTERN = Pattern.compile('^[A-Z]{3}$');
    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String baseCode = normalizeCurrencyCode(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies are required');
        }

        Set<String> normalizedQuoteCodes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            normalizedQuoteCodes.add(normalizeCurrencyCode(quoteCurrency));
        }

        String symbols = buildSymbols(normalizedQuoteCodes);

        HttpRequest request = new HttpRequest();
        request.setMethod('GET');
        request.setEndpoint(ENDPOINT + '?base=' + baseCode + '&symbols=' + symbols);
        request.setHeader('Accept', 'application/json');

        HttpResponse response = sendWithRetry(request);

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + response.getStatusCode()
            );
        }

        return parseRates(response.getBody(), normalizedQuoteCodes);
    }

    private static String buildSymbols(Set<String> quoteCodes) {
        List<String> sortedCodes = new List<String>(quoteCodes);
        sortedCodes.sort();

        String result = '';
        for (String code : sortedCodes) {
            if (result.length() > 0) {
                result += ',';
            }
            result += code;
        }

        return result;
    }

    private static HttpResponse sendWithRetry(HttpRequest request) {
        Http http = new Http();
        HttpResponse response = null;

        try {
            response = http.send(request);
        } catch (CalloutException ex) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + ex.getMessage());
        }

        if (response == null) {
            throw new ExchangeRateException('No response received from exchange rate provider');
        }

        if (response.getStatusCode() == 503) {
            try {
                response = http.send(request);
            } catch (CalloutException ex) {
                throw new ExchangeRateException('Exchange rate callout failed: ' + ex.getMessage());
            }

            if (response == null) {
                throw new ExchangeRateException('No response received from exchange rate provider');
            }
        }

        return response;
    }

    private static String normalizeCurrencyCode(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code is required');
        }

        String normalized = code.trim().toUpperCase();

        if (!CURRENCY_PATTERN.matcher(normalized).matches()) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }

        return normalized;
    }

    private static Map<String, Decimal> parseRates(String body, Set<String> requestedCodes) {
        Object parsed = null;

        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception ex) {
            throw new ExchangeRateException('Could not parse FX response');
        }

        Map<String, Object> payload = null;

        try {
            payload = (Map<String, Object>) parsed;
        } catch (Exception ex) {
            throw new ExchangeRateException('Could not parse FX response');
        }

        if (payload == null) {
            throw new ExchangeRateException('Could not parse FX response');
        }

        Object ratesObject = payload.get('rates');
        Map<String, Object> rates = null;

        try {
            rates = (Map<String, Object>) ratesObject;
        } catch (Exception ex) {
            throw new ExchangeRateException('Missing FX rates');
        }

        if (rates == null) {
            throw new ExchangeRateException('Missing FX rates');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String requestedCode : requestedCodes) {
            if (!rates.containsKey(requestedCode)) {
                throw new ExchangeRateException('Missing FX rate for ' + requestedCode);
            }

            Object rateValue = rates.get(requestedCode);
            Decimal rate;

            if (rateValue instanceof Decimal) {
                rate = (Decimal) rateValue;
            } else if (rateValue == null) {
                throw new ExchangeRateException('Invalid FX rate for ' + requestedCode);
            } else {
                try {
                    rate = Decimal.valueOf(String.valueOf(rateValue));
                } catch (Exception ex) {
                    throw new ExchangeRateException('Invalid FX rate for ' + requestedCode);
                }
            }

            result.put(requestedCode, rate);
        }

        return result;
    }
}
