public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        Set<Id> queryableAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                queryableAccountIds.add(accountId);
            }
        }

        if (queryableAccountIds.isEmpty()) {
            return contactsByDomain;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :queryableAccountIds
            WITH USER_MODE
        ];

        for (Contact contactRecord : contacts) {
            if (contactRecord.Email == null) {
                continue;
            }

            String normalizedEmail = contactRecord.Email.trim();
            if (normalizedEmail.length() == 0) {
                continue;
            }

            Integer domainSeparatorIndex = normalizedEmail.lastIndexOf('@');
            if (domainSeparatorIndex < 0 || domainSeparatorIndex == normalizedEmail.length() - 1) {
                continue;
            }

            String emailDomain = normalizedEmail.substring(domainSeparatorIndex + 1).trim().toLowerCase();
            if (emailDomain.length() == 0) {
                continue;
            }

            List<Contact> contactsForDomain = contactsByDomain.get(emailDomain);
            if (contactsForDomain == null) {
                contactsForDomain = new List<Contact>();
                contactsByDomain.put(emailDomain, contactsForDomain);
            }

            contactsForDomain.add(contactRecord);
        }

        return contactsByDomain;
    }
}
