public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> amountsByAccountId = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return amountsByAccountId;
        }

        Set<Id> accountIdsForQuery = new Set<Id>();

        for (Id accountId : accountIds) {
            if (accountId == null) {
                continue;
            }

            if (accountId.getSObjectType() == Account.SObjectType) {
                amountsByAccountId.put(accountId, Decimal.valueOf(0));
                accountIdsForQuery.add(accountId);
            }
        }

        if (accountIdsForQuery.isEmpty()) {
            return amountsByAccountId;
        }

        for (AggregateResult aggregateResult : [
            SELECT AccountId, SUM(Amount) wonAmount
            FROM Opportunity
            WHERE AccountId IN :accountIdsForQuery
                AND IsWon = true
                AND CloseDate = THIS_YEAR
            GROUP BY AccountId
            WITH USER_MODE
        ]) {
            Id accountId = (Id) aggregateResult.get('AccountId');
            Decimal wonAmount = (Decimal) aggregateResult.get('wonAmount');

            if (accountId != null && amountsByAccountId.containsKey(accountId)) {
                amountsByAccountId.put(accountId, wonAmount == null ? Decimal.valueOf(0) : wonAmount);
            }
        }

        return amountsByAccountId;
    }
}
