            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void validateInsert() {
        super.validateInsert();
        validateAmountNegative();
    }

    public override void validateUpdate() {
        super.validateUpdate();
        validateAmountNegative();
        validateClosedWonAmountChange();
    }

    private void validateAmountNegative() {
        List<Opportunity> opportunities = (List<Opportunity>) getRecords();

        for (Opportunity opportunity : opportunities) {
            if (opportunity.Amount != null && opportunity.Amount < 0) {
                error('Amount cannot be negative.', opportunity, Opportunity.Amount);
            }
        }
    }

    private void validateClosedWonAmountChange() {
        List<Opportunity> opportunities = (List<Opportunity>) getRecords();

        for (Opportunity opportunity : opportunities) {
            Opportunity oldOpportunity = (Opportunity) Trigger.oldMap.get(opportunity.Id);

            if (oldOpportunity == null) {
                continue;
            }

            if (oldOpportunity.StageName == 'Closed Won' &&
                hasAmountChanged(oldOpportunity.Amount, opportunity.Amount)) {
                error('Amount cannot change on a won opportunity.', opportunity, Opportunity.Amount);
            }
        }
    }

    private static Boolean hasAmountChanged(Decimal oldAmount, Decimal newAmount) {
        if (oldAmount == null) {
            return newAmount != null;
        }

        if (newAmount == null) {
            return true;
        }

        return oldAmount != newAmount;
    }
}
