public with sharing class CaseEscalationService {
    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason must not be blank.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        if (cases == null || cases.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = null;
        Date tomorrow = Date.today().addDays(1);

        for (Case c : cases) {
            if (c == null) {
                continue;
            }

            if (c.Status == 'Closed' || c.IsEscalated == true) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';

            if (uow == null) {
                uow = Application.UnitOfWork.newInstance();
            }

            uow.registerDirty(c);

            Task escalationTask = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = tomorrow,
                Priority = 'High'
            );

            uow.registerNew(escalationTask);
        }

        if (uow != null) {
            uow.commitWork();
        }
    }
}
