public class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> createdAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return createdAccounts;
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType> {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        Map<String, Schema.SObjectField> accountFields =
            Account.SObjectType.getDescribe().fields.getMap();
        Map<String, Schema.SObjectField> contactFields =
            Contact.SObjectType.getDescribe().fields.getMap();

        Schema.SObjectField childToParentField = contactFields.get('AccountId');
        Schema.SObjectField parentToChildField = accountFields.get('Id');

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account account = new Account(Name = accountName);
            uow.registerNew(account);
            createdAccounts.add(account);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                if (String.isBlank(lastName)) {
                    continue;
                }

                Contact contact = new Contact(LastName = lastName);
                uow.registerNew(contact);
                uow.registerRelationship(
                    account,
                    contact,
                    childToParentField,
                    parentToChildField
                );
            }
        }

        uow.commitWork();
        return createdAccounts;
    }
}
