/**
 * Synchronizes newly created Accounts to the ERP.
 *
 * Deviation notes:
 * - HTTP callouts cannot be executed directly from an Apex trigger, so this is
 *   implemented as Queueable Apex.
 * - The ticket asks for one ERP request per new Account. This class sends a
 *   one-customer JSON array per callout to preserve that traceability.
 * - For a batch insert of 200 Accounts, issuing 200 callouts in a single
 *   Apex transaction would exceed governor limits. Therefore each Queueable
 *   job processes only up to ACCOUNTS_PER_JOB Accounts and chains the rest.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {
    private static final String ERP_ENDPOINT = 'callout:ERP/api/customers';

    // Keep well below the maximum callouts per transaction while still
    // supporting a 200-record marketplace insert with only four chained jobs.
    private static final Integer ACCOUNTS_PER_JOB = 50;

    private final List<Id> accountIds;
    private final Integer startIndex;

    public ErpCustomerSync(List<Id> accountIds) {
        this(accountIds, 0);
    }

    private ErpCustomerSync(List<Id> accountIds, Integer startIndex) {
        this.accountIds = accountIds == null ? new List<Id>() : accountIds;
        this.startIndex = startIndex == null ? 0 : startIndex;
    }

    public static void enqueueAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<Id> ids = new List<Id>();
        for (Account account : accounts) {
            if (account != null && account.Id != null) {
                ids.add(account.Id);
            }
        }

        if (!ids.isEmpty()) {
            System.enqueueJob(new ErpCustomerSync(ids));
        }
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty() || startIndex >= accountIds.size()) {
            return;
        }

        Integer endIndex = Math.min(accountIds.size(), startIndex + ACCOUNTS_PER_JOB);

        List<Id> idsToProcess = new List<Id>();
        for (Integer i = startIndex; i < endIndex; i++) {
            idsToProcess.add(accountIds[i]);
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :idsToProcess
        ]);

        for (Id accountId : idsToProcess) {
            Account account = accountsById.get(accountId);
            if (account != null) {
                syncAccount(account);
            }
        }

        if (endIndex < accountIds.size()) {
            System.enqueueJob(new ErpCustomerSync(accountIds, endIndex));
        }
    }

    private static void syncAccount(Account account) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ERP_ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setTimeout(120000);
        request.setBody(buildRequestBody(account));

        // ERP returns 202 Accepted. Error handling and retries are out of scope.
        new Http().send(request);
    }

    private static String buildRequestBody(Account account) {
        JSONGenerator generator = JSON.createGenerator(false);

        generator.writeStartArray();
        generator.writeStartObject();

        generator.writeFieldName('salesforceId');
        generator.writeString(String.valueOf(account.Id.to18()));

        generator.writeFieldName('name');
        writeNullableString(generator, blankToNull(account.Name));

        generator.writeFieldName('country');
        writeNullableString(generator, blankToNull(account.BillingCountry));

        generator.writeEndObject();
        generator.writeEndArray();

        return generator.getAsString();
    }

    private static void writeNullableString(JSONGenerator generator, String value) {
        if (value == null) {
            generator.writeNull();
        } else {
            generator.writeString(value);
        }
    }

    private static String blankToNull(String value) {
        if (value == null) {
            return null;
        }

        if (value.trim() == '') {
            return null;
        }

        return value;
    }
}
