/*
 * Uses a partial-DML insert instead of one insert per opportunity.
 * Individual inserts for 150-250 opportunities would hit the 150 DML statement limit.
 * Partial DML still reports each opportunity's task outcome independently.
 */
public with sharing class FollowUpTaskService {
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null) {
            return failedOpportunityIds;
        }

        Set<Id> opportunityIdSet = new Set<Id>();
        for (Id oppId : opportunityIds) {
            if (oppId == null) {
                continue;
            }

            if (oppId.getSobjectType() == Opportunity.SObjectType) {
                opportunityIdSet.add(oppId);
            } else {
                failedOpportunityIds.add(oppId);
            }
        }

        if (opportunityIdSet.isEmpty()) {
            return failedOpportunityIds;
        }

        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>();
        try {
            opportunities = new Map<Id, Opportunity>(
                [
                    SELECT Id, Name, OwnerId
                    FROM Opportunity
                    WHERE Id IN :opportunityIdSet
                ]
            );
        } catch (Exception e) {
            failedOpportunityIds.addAll(opportunityIdSet);
            return failedOpportunityIds;
        }

        List<Task> tasks = new List<Task>();
        List<Id> taskSourceOpportunityIds = new List<Id>();
        Date activityDate = Date.today().addDays(7);

        for (Id oppId : opportunityIdSet) {
            Opportunity opp = opportunities.get(oppId);

            if (opp == null) {
                failedOpportunityIds.add(oppId);
                continue;
            }

            Task followUp = new Task();
            followUp.WhatId = opp.Id;
            followUp.OwnerId = opp.OwnerId;
            followUp.Subject = 'Follow up: ' + opp.Name;
            followUp.ActivityDate = activityDate;
            followUp.Status = 'Not Started';
            followUp.Priority = 'Normal';

            tasks.add(followUp);
            taskSourceOpportunityIds.add(opp.Id);
        }

        if (tasks.isEmpty()) {
            return failedOpportunityIds;
        }

        try {
            Database.SaveResult[] results = Database.insert(tasks, false);

            for (Integer i = 0; i < taskSourceOpportunityIds.size(); i++) {
                if (i >= results.size() || !results[i].isSuccess()) {
                    failedOpportunityIds.add(taskSourceOpportunityIds[i]);
                }
            }
        } catch (Exception e) {
            failedOpportunityIds.addAll(taskSourceOpportunityIds);
        }

        return failedOpportunityIds;
    }
}
```

Difference from the prompt: I do **not** schedule one `@future` call per opportunity. A 200-record CPQ batch would exceed the Apex limit of 50 future-method calls per transaction. The trigger instead collects unique affected `AccountId`s for the transaction/event and schedules **one** `@future` call. I also include the old `AccountId` when an opportunity is moved between accounts, even if only the account changed, to prevent stale `Rating` values on the former account.

