```apex
/*
 * Requested pattern: call Messaging.sendEmail once per opportunity so one failure does not
 * stop the remaining sends.
 *
 * This is generally a bad idea in production Apex. The preferred bulk pattern is to build a
 * single List<Messaging.SingleEmailMessage> and call Messaging.sendEmail once. To isolate
 * failures, validate or guard each message while constructing the list. If per-message delivery
 * isolation is truly required, batch smaller groups instead of doing 200 individual sendEmail
 * calls, which increases CPU time and makes limit behavior harder to reason about.
 *
 * This class is written without sharing because it is intended for a scheduled job that passes
 * already-authorized opportunity Ids. If exposing this method to arbitrary callers, enforce
 * object/field access or run it as with sharing.
 */
public without sharing class RenewalReminderService {

    private static final Integer MAX_EMAIL_LIMIT = 200;

    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer sentSuccessfully = 0;
        Integer emailAttempts = 0;

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return sentSuccessfully;
        }

        // Deduplicate while preserving the caller's order.
        Set<Id> queryIds = new Set<Id>();
        List<Id> orderedUniqueIds = new List<Id>();
        for (Id oppId : opportunityIds) {
            if (oppId != null && !queryIds.contains(oppId)) {
                queryIds.add(oppId);
                orderedUniqueIds.add(oppId);
            }
        }

        if (orderedUniqueIds.isEmpty()) {
            return sentSuccessfully;
        }

        // Bulk-safe single SOQL query.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, OwnerId, CloseDate
                FROM Opportunity
                WHERE Id IN :queryIds
            ]
        );

        for (Id oppId : orderedUniqueIds) {
            if (emailAttempts >= MAX_EMAIL_LIMIT) {
                break;
            }

            Opportunity opp = opportunitiesById.get(oppId);
            if (opp == null || opp.OwnerId == null) {
                continue;
            }

            String oppName = opp.Name == null ? '' : opp.Name;
            String subject = 'Renewal due: ' + oppName;

            // Email subject has a 255-character limit.
            if (subject.length() > 255) {
                subject = subject.substring(0, 255);
            }

            String closeDateFormatted = opp.CloseDate == null ? 'Unknown' : opp.CloseDate.format();
            String closeDateIso = opp.CloseDate == null ? 'Unknown' : String.valueOf(opp.CloseDate);
            String body =
                'The renewal/close date for opportunity ' + oppName +
                ' is ' + closeDateFormatted + ' (' + closeDateIso + ').';

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject(subject);
            email.setPlainTextBody(body);

            List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();
            emails.add(email);

            emailAttempts++;

            try {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(emails);

                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentSuccessfully++;
                }
            } catch (Exception ex) {
                // Intentionally continue so one failed email does not stop the remaining sends.
                System.debug(LoggingLevel.WARN,
                    'RenewalReminderService failed to send reminder for opportunity ' + oppId +
                    ': ' + ex.getMessage()
                );
            }
        }

        return sentSuccessfully;
    }
}
