    columns = COLUMNS;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts;

    get data() {
        if (this.wiredContacts && this.wiredContacts.data) {
            return this.wiredContacts.data;
        }
        return [];
    }

    async handleSave(event) {
        const detail = event.detail;

        // Standard datatable save events expose the rows at detail.draft;
        // accept an array on detail as well so the handler is robust.
        const drafts = detail.draft
            ? detail.draft
            : Array.isArray(detail)
            ? detail
            : [];

        // Fire one updateRecord per draft, in parallel (all calls start
        // synchronously, before we await), and wait for all of them.
        const promises = drafts.map((draft) =>
            updateRecord({ fields: { ...draft } })
        );

        try {
            await Promise.all(promises);

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Contacts updated',
                    variant: 'success'
                })
            );

            this.draftValues = [];

