export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities = [];

    columns = [
        { label: 'Name', fieldName: 'Name' },
        { label: 'Stage', fieldName: 'StageName' },
        { label: 'Amount', fieldName: 'Amount', type: 'currency' },
        {
            type: 'action',
            typeAttributes: {
                rowActions: [
                    { label: 'View', name: 'view' },
                    { label: 'Edit', name: 'edit' },
                    { label: 'Delete', name: 'delete' }
                ]
            }
        }
    ];

    async handleRowAction(event) {
        const action = event?.detail?.action;
        const row = event?.detail?.row;

        if (!action || !row) {
            return;
        }

        if (action.name === 'view') {
            this.navigateToRecord(row.Id, 'view');
        } else if (action.name === 'edit') {
            this.navigateToRecord(row.Id, 'edit');
        } else if (action.name === 'delete') {
            const confirmed = await LightningConfirm.open({
                label: 'Confirm Opportunity Deletion',
                message: 'Are you sure you want to delete this opportunity?',
                variant: 'destructive'
            });

            if (!confirmed) {
                return;
            }

            try {
                await deleteRecord(row.Id);

                const currentOpportunities = Array.isArray(this.opportunities)
                    ? this.opportunities
                    : [];

                this.opportunities = currentOpportunities.filter(
                    (record) => record?.Id !== row.Id
                );

                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Opportunity deleted',
                        message: 'The opportunity was deleted successfully.',
                        variant: 'success'
                    })
                );
            } catch (error) {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Delete failed',
                        message: error?.body?.message,
                        variant: 'error'
                    })
                );
            }
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: 'Opportunity',
                actionName
            }
        });
    }
