    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleFieldChange(event) {
        const target = event.target;
        const field = target && target.dataset ? target.dataset.field : null;

        const value =
            event.detail && 'value' in event.detail
                ? event.detail.value
                : target
                  ? target.value
                  : undefined;

        switch (field) {
            case 'fullName':
                this.fullName = value;
                break;
            case 'email':
                this.email = value;
                break;
            case 'company':
                this.company = value;
                break;
            default:
                break;
        }
    }

    handleRegister() {
        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );

        const emailValue = typeof this.email === 'string' ? this.email : '';
        const trimmedEmail = emailValue.trim();
        const domain = trimmedEmail.includes('@')
            ? trimmedEmail.split('@').pop().toLowerCase()
            : '';

        if (emailInput) {
            if (FREE_EMAIL_DOMAINS.has(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        let allValid = true;
        this.template.querySelectorAll('lightning-input').forEach((input) => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                const message =
                    error && error.body ? error.body.message : undefined;

                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message
                    })
                );
            });
    }
}
