```java
/**
 * Service to maintain a donor contact's current employer in NPSP.
 *
 * The standard NPSP mechanism for designating a primary employer affiliation is
 * to update the Contact primary affiliation lookup. NPSP trigger logic creates or
 * retires the underlying npe5__Affiliation__c records, sets the affiliation to
 * Current and Primary, and marks the previous primary affiliation as Former with
 * an end date. This class intentionally does not manually manipulate Affiliation
 * records, which helps preserve NPSP's standard primary affiliation behavior and
 * prevents duplicate affiliations.
 */
public with sharing class EmployerService {
    /**
     * Sets the primary employer affiliation for the supplied contact/organization
     * pairs.
     *
     * @param employerByContactId Map of Contact Id to desired Organization Account Id
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Filter out invalid entries while preserving a single bulkified path.
        Map<Id, Id> desiredEmployersByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id organizationAccountId = employerByContactId.get(contactId);
            if (contactId != null && organizationAccountId != null) {
                desiredEmployersByContactId.put(contactId, organizationAccountId);
            }
        }

        if (desiredEmployersByContactId.isEmpty()) {
            return;
        }

        // Query only the contacts being considered.
        List<Contact> contacts = [
            SELECT Id,
                npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :desiredEmployersByContactId.keySet()
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : contacts) {
            Id desiredOrganizationAccountId = desiredEmployersByContactId.get(contact.Id);

            // If the requested organization is already the contact's primary affiliation,
            // make no change. This prevents redundant updates and duplicate affiliations.
            if (desiredOrganizationAccountId == null || contact.npsp__Primary_Affiliation__c == desiredOrganizationAccountId) {
                continue;
            }

            // Update only the primary affiliation lookup. Do not set Contact.AccountId,
            // which would incorrectly move the contact out of their household account.
            Contact updatedContact = new Contact(
                Id = contact.Id,
                npsp__Primary_Affiliation__c = desiredOrganizationAccountId
            );

            contactsToUpdate.add(updatedContact);
        }

        // Single bulk DML statement. NPSP triggers maintain the Affiliation records.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
