public with sharing class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.size() == 0) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('members must not contain null Contact records.');
            }
        }

        Schema.RecordTypeInfo householdRecordTypeInfo =
            Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName().get('HH_Account');

        if (householdRecordTypeInfo == null || !householdRecordTypeInfo.isAvailable()) {
            throw new IllegalArgumentException('Household Account record type HH_Account is not available.');
        }

        Savepoint transactionSavepoint = Database.setSavepoint();

        try {
            Account household = new Account();
            household.RecordTypeId = householdRecordTypeInfo.getRecordTypeId();
            insert household;

            for (Contact member : members) {
                member.AccountId = household.Id;
            }

            insert members;

            Contact primaryContact = members[0];

            update new Account(
                Id = household.Id,
                npe01__One2OneContact__c = primaryContact.Id
            );

            return household.Id;
        } catch (Exception ex) {
            Database.rollback(transactionSavepoint);
            throw ex;
        }
    }
}
