```apex
public with sharing class FamilyService {
    private static final String REL_TYPE_PARENT = 'Parent';
    private static final String REL_STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (isValidContactPair(childId, parentId)) {
                contactIds.add(childId);
                contactIds.add(parentId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        // One query only. This finds any existing relationship between these contacts in either direction.
        List<npe4__Relationship__c> existingRelationships = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
            WITH USER_MODE
        ];

        Set<String> existingPairs = new Set<String>();

        for (npe4__Relationship__c rel : existingRelationships) {
            if (rel.npe4__Contact__c != null && rel.npe4__RelatedContact__c != null) {
                existingPairs.add(makePairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            }
        }

        List<SObject> relationshipsToCreate = new List<SObject>();
        Set<String> queuedPairs = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (!isValidContactPair(childId, parentId)) {
                continue;
            }

            String pairKey = makePairKey(childId, parentId);

            if (existingPairs.contains(pairKey) || queuedPairs.contains(pairKey)) {
                continue;
            }

            queuedPairs.add(pairKey);

            // Create the child-to-parent relationship only.
            // NPSP's List Setting reciprocal method creates and links the parent-to-child relationship.
            relationshipsToCreate.add(
                new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = REL_TYPE_PARENT,
                    npe4__Status__c = REL_STATUS_CURRENT
                )
            );
        }

        if (relationshipsToCreate.isEmpty()) {
            return;
        }

        // Enforce field-level security for DML.
        relationshipsToCreate = Security.stripInaccessible(
            AccessType.CREATABLE,
            relationshipsToCreate
        ).getRecords();

        if (relationshipsToCreate.isEmpty()) {
            return;
        }

        // One DML statement of our own.
        Database.insert(relationshipsToCreate, false);
    }

    private static Boolean isValidContactPair(Id childId, Id parentId) {
        return childId != null
            && parentId != null
            && childId != parentId
            && childId.getSObjectType() == Contact.SObjectType
            && parentId.getSObjectType() == Contact.SObjectType;
    }

    private static String makePairKey(Id a, Id b) {
        String x = String.valueOf(a);
        String y = String.valueOf(b);

        return x.compareTo(y) <= 0
            ? x + '|' + y
            : y + '|' + x;
    }
}
