/**
 * Trigger Actions Framework (0.3.4) action for Contact:
 * two contacts that belong to the same Account may not use the same email address
 * (compared case-insensitively). Contacts without an Account or without an Email are ignored.
 *
 * Registered through Trigger_Action__mdt records:
 *   TA_Contact_PreventDuplicateEmail_BI  -> Contact before insert
 *   TA_Contact_PreventDuplicateEmail_BU  -> Contact before update
 *
 * Behaviour:
 *  - Bulk safe: a single SOQL query per trigger execution for the whole batch
 *    (zero queries when no record changes its Account/Email combination).
 *  - Record level addError(message, false), so valid records of a partial save still commit.
 *  - Records are evaluated in save order: the first contact that claims an Account/Email
 *    combination is accepted, every later one that would share it is rejected.
 *  - On update only contacts whose Account/Email combination actually changes are checked
 *    (pre-existing legacy duplicates keep being editable) and a contact is never counted as a
 *    conflict with itself.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_ERROR =
            'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforce(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforce(triggerNew, triggerOld);
    }

    private static void enforce(List<SObject> newRecords, List<SObject> oldRecords) {
        List<Contact> incoming = asContacts(newRecords);
        Map<Id, Contact> previous = indexById(asContacts(oldRecords));

        // --------------------------------------------------------------------------
        // 1. Which records does the rule apply to in this save?
        //    Order of Trigger.new is preserved, which is what makes "the first one wins" work.
        // --------------------------------------------------------------------------
        List<Contact> candidates = new List<Contact>();
        List<String> candidateKeys = new List<String>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emailFilters = new Set<String>();

        for (Contact candidate : incoming) {
            Contact prior = previous.get(candidate.Id);

            // Trigger.new can contain partial records: fall back to the stored value for a
            // field this particular save does not touch.
            Id accountId = candidate.AccountId != null
                    ? candidate.AccountId
                    : (prior == null ? null : prior.AccountId);
            String rawEmail = String.isNotBlank(candidate.Email)
                    ? candidate.Email
                    : (prior == null ? null : prior.Email);

            String key = buildKey(accountId, rawEmail);
            if (key == null) {
                continue; // no Account or no Email: nothing to enforce
            }
            if (prior != null && key == buildKey(prior.AccountId, prior.Email)) {
                continue; // Account/Email combination unchanged: unrelated edits stay allowed
            }

            candidates.add(candidate);
            candidateKeys.add(key);
            accountIds.add(accountId);
            emailFilters.add(normalize(rawEmail)); // lower case: SOQL text comparison ignores case
            emailFilters.add(rawEmail);            // exact value as well, belt and braces
        }

        if (candidates.isEmpty()) {
            return;
        }

        // --------------------------------------------------------------------------
        // 2. One query for the entire batch: every contact that already occupies one of the
        //    Account/Email combinations being written. Counts, so legacy duplicates holding
        //    the same combination are handled correctly.
        // --------------------------------------------------------------------------
        Map<String, Integer> holdersByAccountEmail = new Map<String, Integer>();
        for (Contact existing : [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                AND Email IN :emailFilters
        ]) {
            adjust(holdersByAccountEmail, buildKey(existing.AccountId, existing.Email), 1);
        }

        // --------------------------------------------------------------------------
        // 3. Contacts being updated still sit in the database with their old Account/Email.
        //    Retire those combinations: nobody conflicts with itself, and nobody conflicts
        //    with a value this very save is moving away from (e.g. an email swap).
        // --------------------------------------------------------------------------
        for (Contact candidate : candidates) {
            Contact prior = previous.get(candidate.Id);
            if (prior == null) {
                continue;
            }
            adjust(holdersByAccountEmail, buildKey(prior.AccountId, prior.Email), -1);
        }

        // --------------------------------------------------------------------------
        // 4. Claim combinations in save order. The first record that takes a free one passes;
        //    every later record that wants it gets a record level error only (partial save).
        // --------------------------------------------------------------------------
        for (Integer i = 0; i < candidates.size(); i++) {
            String key = candidateKeys[i];
            if (holdersByAccountEmail.containsKey(key)) {
                candidates[i].addError(DUPLICATE_EMAIL_ERROR, false);
            } else {
                adjust(holdersByAccountEmail, key, 1);
            }
        }
    }

    /** Account + case-insensitive email, or null when the rule does not apply to the record. */
    private static String buildKey(Id accountId, String email) {
        String normalizedEmail = normalize(email);
        return (accountId == null || normalizedEmail == null) ? null : accountId + '|' + normalizedEmail;
    }

    private static String normalize(String email) {
        return String.isBlank(email) ? null : email.toLowerCase();
    }

    /** Track how many committed contacts occupy a key; the key disappears at zero. */
    private static void adjust(Map<String, Integer> counts, String key, Integer delta) {
        if (key == null) {
            return;
        }
        Integer remaining = (counts.containsKey(key) ? counts.get(key) : 0) + delta;
        if (remaining <= 0) {
            counts.remove(key);
        } else {
            counts.put(key, remaining);
        }
    }

    private static List<Contact> asContacts(List<SObject> records) {
        List<Contact> contacts = new List<Contact>();
        if (records == null) {
            return contacts;
        }
        for (SObject record : records) {
            if (record instanceof Contact) {
                contacts.add((Contact) record); // same instance, so addError() applies to Trigger.new
            }
        }
        return contacts;
    }

    private static Map<Id, Contact> indexById(List<Contact> records) {
        Map<Id, Contact> byId = new Map<Id, Contact>();
        for (Contact record : records) {
            if (record != null && record.Id != null) {
                byId.put(record.Id, record);
            }
        }
        return byId;
    }
}
